mod errors {
    const BASE: u32 = 100;
    const STEP: u32 = 2;

    #[core::contracterror]
    #[derive(Copy, Clone, Debug, Eq, PartialEq)]
    #[repr(u32)]
    pub enum TokenError {
        NotInitialized = BASE,
        InsufficientBalance = BASE + STEP,
        Overflow = external_const::LIMIT,
        Unnumbered,
    }
}

// #[contracterror] in a comment must not be parsed
const NOTE: &str = "#[contracterror] in a string must not be parsed either";

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum DError {
    /* inline */ Alpha = 1, // trailing comment
    Beta = 1 + 1,
}
